PRAGMA threads=4;

CREATE TABLE IF NOT EXISTS trade_cal (
    "exchange" VARCHAR,
    "cal_date" DATE,
    "is_open" DOUBLE,
    "pretrade_date" DATE,
    PRIMARY KEY ("exchange", "cal_date")
);

CREATE TABLE IF NOT EXISTS stock_basic (
    "ts_code" VARCHAR,
    "symbol" VARCHAR,
    "name" VARCHAR,
    "area" VARCHAR,
    "industry" VARCHAR,
    "cnspell" VARCHAR,
    "market" VARCHAR,
    "list_date" DATE,
    "act_name" VARCHAR,
    "act_ent_type" VARCHAR,
    PRIMARY KEY ("ts_code")
);

CREATE TABLE IF NOT EXISTS daily (
    "ts_code" VARCHAR,
    "trade_date" DATE,
    "open" DOUBLE,
    "high" DOUBLE,
    "low" DOUBLE,
    "close" DOUBLE,
    "pre_close" DOUBLE,
    "change" DOUBLE,
    "pct_chg" DOUBLE,
    "vol" DOUBLE,
    "amount" DOUBLE,
    PRIMARY KEY ("ts_code", "trade_date")
);

COMMENT ON COLUMN daily."open" IS '开盘价（元，未复权）';
COMMENT ON COLUMN daily."high" IS '最高价（元，未复权）';
COMMENT ON COLUMN daily."low" IS '最低价（元，未复权）';
COMMENT ON COLUMN daily."close" IS '收盘价（元，未复权）';
COMMENT ON COLUMN daily."pre_close" IS '昨收价（元，未复权）';
COMMENT ON COLUMN daily."vol" IS '成交量（手，1 手 = 100 股）';
COMMENT ON COLUMN daily."amount" IS '成交额（千元）';

CREATE TABLE IF NOT EXISTS daily_basic (
    "ts_code" VARCHAR,
    "trade_date" DATE,
    "close" DOUBLE,
    "turnover_rate" DOUBLE,
    "turnover_rate_f" DOUBLE,
    "volume_ratio" DOUBLE,
    "pe" DOUBLE,
    "pe_ttm" DOUBLE,
    "pb" DOUBLE,
    "ps" DOUBLE,
    "ps_ttm" DOUBLE,
    "dv_ratio" DOUBLE,
    "dv_ttm" DOUBLE,
    "total_share" DOUBLE,
    "float_share" DOUBLE,
    "free_share" DOUBLE,
    "total_mv" DOUBLE,
    "circ_mv" DOUBLE,
    PRIMARY KEY ("ts_code", "trade_date")
);

COMMENT ON COLUMN daily_basic."close" IS '收盘价（元，未复权）';
COMMENT ON COLUMN daily_basic."turnover_rate" IS '换手率（%）';
COMMENT ON COLUMN daily_basic."turnover_rate_f" IS '换手率（自由流通股本，%）';
COMMENT ON COLUMN daily_basic."volume_ratio" IS '量比';
COMMENT ON COLUMN daily_basic."pe" IS '市盈率（动态）';
COMMENT ON COLUMN daily_basic."pe_ttm" IS '市盈率（TTM）';
COMMENT ON COLUMN daily_basic."pb" IS '市净率';
COMMENT ON COLUMN daily_basic."ps" IS '市销率';
COMMENT ON COLUMN daily_basic."ps_ttm" IS '市销率（TTM）';
COMMENT ON COLUMN daily_basic."dv_ratio" IS '股息率（%）';
COMMENT ON COLUMN daily_basic."dv_ttm" IS '滚动股息率（%）';
COMMENT ON COLUMN daily_basic."total_share" IS '总股本（万股）';
COMMENT ON COLUMN daily_basic."float_share" IS '流通股本（万股）';
COMMENT ON COLUMN daily_basic."free_share" IS '自由流通股本（万股）';
COMMENT ON COLUMN daily_basic."total_mv" IS '总市值（万元）';
COMMENT ON COLUMN daily_basic."circ_mv" IS '流通市值（万元）';

CREATE TABLE IF NOT EXISTS adj_factor (
    "ts_code" VARCHAR,
    "trade_date" DATE,
    "adj_factor" DOUBLE,
    PRIMARY KEY ("ts_code", "trade_date")
);

COMMENT ON COLUMN adj_factor."adj_factor" IS '复权因子（后复权 = 收盘价 × 因子）';

